from pptx import Presentation

pptx_path = "/root/Awesome-Agent-Papers.pptx"
prs = Presentation(pptx_path)

for i, slide in enumerate(prs.slides):
    print(f"Slide {i+1}")
    for shape in slide.shapes:
        if hasattr(shape, "text"):
            print(f"  Shape: {shape.name}, Text: {shape.text}")

from pptx import Presentation

pptx_path = "/root/Awesome-Agent-Papers_processed.pptx"
prs = Presentation(pptx_path)

for i, slide in enumerate(prs.slides):
    print(f"Slide {i+1}")
    for shape in slide.shapes:
        if hasattr(shape, "text"):
            # If it's the shape we moved, print its position and formatting
            print(f"  Shape: {shape.name}, Text: {shape.text[:50]}...")
            if not shape.is_placeholder and i > 0:
                print(f"    Pos: left={shape.left}, top={shape.top}, width={shape.width}")
                if hasattr(shape, "text_frame"):
                    for p in shape.text_frame.paragraphs:
                        if p.runs:
                            run = p.runs[0]
                            print(f"    Font: {run.font.name}, Size: {run.font.size}, Color: {run.font.color.rgb if run.font.color and hasattr(run.font.color, 'rgb') else 'None'}")

from pptx import Presentation

pptx_path = "/root/Awesome-Agent-Papers_processed.pptx"
prs = Presentation(pptx_path)

ref_slide = prs.slides[-1]
print(f"Slide {len(prs.slides)}: {ref_slide.shapes.title.text}")
for shape in ref_slide.shapes:
    if shape.has_text_frame and shape != ref_slide.shapes.title:
        print("Content:")
        for p in shape.text_frame.paragraphs:
            print(f"  - {p.text}")
